package io.screentrace.parser.jsp;
import io.screentrace.core.ApplicationGraph;import io.screentrace.core.ApplicationGraph.*;import io.screentrace.scanner.ProjectScanner.ProjectInventory;import io.screentrace.scanner.SafeProjectFiles;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;
/** Finite named fragment calls. Predicates and nonliteral parameter expressions are retained, never evaluated. */
public final class ThymeleafFragments {
 private record Call(String template,String fragment,List<String> arguments,String guard){}
 private static List<String> arguments(String value){List<String> result=new ArrayList<>();int begin=0;char quote=0;for(int i=0;i<value.length();i++){char c=value.charAt(i);if(quote!=0){if(c==quote)quote=0;}else if(c=='\''||c=='"')quote=c;else if(c==','){result.add(value.substring(begin,i).strip());begin=i+1;}else if("{}()".indexOf(c)>=0)return List.of();}if(quote!=0)return List.of();if(!value.isBlank())result.add(value.substring(begin).strip());return result;}
 private static Call direct(String expression,String guard){String text=expression.strip();if(text.startsWith("~{")&&text.endsWith("}"))text=text.substring(2,text.length()-1).strip();int split=text.indexOf("::");if(split<1)return null;String template=text.substring(0,split).strip(),part=text.substring(split+2).strip();var matcher=java.util.regex.Pattern.compile("([A-Za-z_][A-Za-z0-9_-]*)\\((.*)\\)").matcher(part);if(!template.matches("[A-Za-z0-9_/-]+")||template.contains("..")||template.startsWith("/")||!matcher.matches())return null;List<String> args=arguments(matcher.group(2));if(args.size()>32)return null;return new Call(template,matcher.group(1),args,guard);}
 private static List<Call> calls(String expression){if(expression==null)return List.of();Call one=direct(expression,null);if(one!=null)return List.of(one);var choice=java.util.regex.Pattern.compile("(?s)^\\s*(\\$\\{[^{}]+})\\s*\\?\\s*(~\\{[^{}]+})\\s*:\\s*(~\\{[^{}]+})\\s*$").matcher(expression);if(!choice.matches())return List.of();Call yes=direct(choice.group(2),choice.group(1)),no=direct(choice.group(3),"!("+choice.group(1)+")");return yes==null||no==null?List.of():List.of(yes,no);}
 public static ApplicationGraph enrich(ApplicationGraph graph,ProjectInventory inventory){Map<String,GraphNode> nodes=new TreeMap<>();graph.nodes().forEach(n->nodes.put(n.id(),n));Map<String,Relationship> edges=new TreeMap<>();graph.relationships().forEach(e->edges.put(e.id(),e));Map<String,List<Map<String,Object>>> refs=new TreeMap<>();List<Diagnostic> diagnostics=new ArrayList<>(graph.diagnostics());ObjectMapper json=new ObjectMapper();
  for(var file:inventory.files()){String owner=inventory.root().relativize(file).toString().replace('\\','/');if(!owner.endsWith(".html"))continue;
   try{String source=SafeProjectFiles.readUtf8Limited(inventory.root(),file,SafeProjectFiles.MAX_JSP_FILE_BYTES);
    for(var tag:MarkupTag.scan(source))if(!tag.closing()&&tag.attribute("th:replace")!=null){String expression=tag.attribute("th:replace");var alternatives=calls(expression);if(alternatives.isEmpty()){diagnostics.add(new Diagnostic("模板片段呼叫無法靜態解析",Confidence.UNRESOLVED,new SourceLocation(owner,tag.line()),"TEMPLATE_FRAGMENT_UNRESOLVED",List.of()));continue;}
     int root=owner.indexOf("/templates/");String base=root>=0?owner.substring(0,root+"/templates/".length()):owner.substring(0,owner.lastIndexOf('/')+1);
     for(var call:alternatives){String target=base+call.template+".html";String text=SafeProjectFiles.readUtf8Limited(inventory.root(),inventory.root().resolve(target),SafeProjectFiles.MAX_JSP_FILE_BYTES);var tags=MarkupTag.scan(text);var definitions=tags.stream().filter(t->!t.closing()&&t.attribute("th:fragment")!=null&&t.attribute("th:fragment").strip().startsWith(call.fragment+"(")).toList();if(definitions.size()!=1)continue;var definition=definitions.get(0);String signature=definition.attribute("th:fragment").strip();if(!signature.endsWith(")"))continue;var parameters=arguments(signature.substring(signature.indexOf('(')+1,signature.length()-1));if(parameters.size()!=call.arguments.size()||parameters.stream().anyMatch(p->!p.matches("[A-Za-z_][A-Za-z0-9_]*")))continue;
      int depth=0,end=-1;for(var t:tags)if(t.start()>=definition.start()&&t.name().equals(definition.name())){if(!t.closing()&&text.charAt(t.end()-1)!='/')depth++;if(t.closing()&&--depth==0){end=t.end()+1;break;}}if(end<0)continue;
      Map<String,String> values=new TreeMap<>(),originals=new TreeMap<>();for(int i=0;i<parameters.size();i++){String a=call.arguments.get(i);originals.put(parameters.get(i),a);if(a.length()>=2&&(a.charAt(0)=='\''&&a.endsWith("'")||a.charAt(0)=='"'&&a.endsWith("\"")))values.put(parameters.get(i),a.substring(1,a.length()-1));}
      int endLine=1+(int)text.substring(0,end).chars().filter(c->c=='\n').count();Map<String,Object> ref=new TreeMap<>();ref.put("ownerFile",owner);ref.put("line",tag.line());ref.put("file",target);ref.put("fragment",call.fragment);ref.put("start",definition.start());ref.put("end",end);ref.put("startLine",definition.line());ref.put("endLine",endLine);ref.put("parameters",values);ref.put("parameterExpressions",originals);ref.put("expression",expression);if(call.guard!=null)ref.put("guard",call.guard);refs.computeIfAbsent(owner,k->new ArrayList<>()).add(ref);
      String fragment=ApplicationGraph.id(NodeType.TEMPLATE_FRAGMENT,target+"#"+call.fragment);var location=new SourceLocation(owner,tag.line());var proof=List.of(new AnalysisEvidence(location,"ThymeleafFragmentParser",ResolutionStatus.INFERRED,json.writeValueAsString(ref)),new AnalysisEvidence(new SourceLocation(target,definition.line()),"ThymeleafFragmentParser",ResolutionStatus.CONFIRMED,"具名片段="+call.fragment+"；參數="+parameters));nodes.putIfAbsent(fragment,new GraphNode(fragment,NodeType.TEMPLATE_FRAGMENT,call.fragment,Map.of("view",target,"fragment",call.fragment),new SourceLocation(target,definition.line()),Confidence.CONFIRMED,proof));
      for(var screen:graph.nodes())if(screen.type()==NodeType.SCREEN&&owner.equals(screen.attributes().get("view"))){String id=ApplicationGraph.id(NodeType.TEMPLATE_FRAGMENT,screen.id()+":"+fragment+":"+tag.line()+":"+Objects.toString(call.guard,""));edges.put(id,new Relationship(id,EdgeType.INCLUDES,screen.id(),fragment,Confidence.INFERRED,location,proof));for(var component:graph.nodes())if(component.type()==NodeType.COMPONENT&&target.equals(component.source().file())&&component.source().line()>=definition.line()&&component.source().line()<=endLine){String contains=ApplicationGraph.id(NodeType.COMPONENT,"fragment:"+screen.id()+":"+component.id());edges.put(contains,new Relationship(contains,EdgeType.CONTAINS,screen.id(),component.id(),Confidence.INFERRED,location,proof));}}
     }
    }
   }catch(Exception error){diagnostics.add(new Diagnostic("模板片段來源無法安全解析",Confidence.UNRESOLVED,new SourceLocation(owner,1),"TEMPLATE_FRAGMENT_UNRESOLVED",List.of()));}
  }
  for(var entry:new ArrayList<>(nodes.entrySet())){var n=entry.getValue();if(n.type()!=NodeType.SCREEN||n.attributes().get("view")==null)continue;var items=refs.get(n.attributes().get("view"));if(items==null)continue;var attrs=new TreeMap<>(n.attributes());try{attrs.put("templateFragments",json.writeValueAsString(items));}catch(Exception ignored){}nodes.put(n.id(),new GraphNode(n.id(),n.type(),n.name(),attrs,n.source(),n.confidence(),n.evidence()));}
  return new ApplicationGraph(graph.application(),List.copyOf(nodes.values()),List.copyOf(edges.values()),diagnostics,graph.apiContracts(),graph.schemaVersion(),graph.behaviors(),graph.validationRules());
 }
}
